 int flb_unescape_string_utf8(const char *in_buf, int sz, char *out_buf)
 {
     uint32_t ch;
     char temp[4];
     const char *end;
     const char *next;
                 int size;


     int count_out = 0;
     int count_in = 0;
     int esc_in = 0;
     int esc_out = 0;

     end = in_buf + sz;
     while (in_buf < end && *in_buf && count_in < sz) {
         next = in_buf + 1;
         if (next < end && *in_buf == '\\') {
             esc_in = 2;
             switch (*next) {
             case '"':
                 ch = '"';
                 break;
             case '\'':
                 ch = '\'';
                 break;
             case '\\':
                 ch = '\\';
                 break;
             case '/':
                 ch = '/';
                 break;
             case 'n':
                 ch = '\n';
                 break;
             case 'b':
                 ch = '\b';
                 break;
             case 't':
                 ch = '\t';
                 break;
             case 'f':
                 ch = '\f';
                 break;
             case 'r':
                 ch = '\r';
                 break;
             default:
                 size = end - next;
                 if (size > 0) {
                     esc_in = u8_read_escape_sequence(next, size, &ch) + 1;
                 }
                 else {
                     /* because char is unsigned char by default on arm, so we need to do a explicit conversion */
                     ch = (uint32_t) (signed char) *in_buf;
                     esc_in = 1;
                 }
             }
         }
         else {
             /* explicit convert char to signed char */
             ch = (uint32_t) (signed char) *in_buf;
             esc_in = 1;
         }

         in_buf += esc_in;
         count_in += esc_in;

         esc_out = u8_wc_toutf8(temp, ch);
         if (esc_out > sz-count_out) {
             flb_error("Crossing over string boundary");
             break;
         }

         if (esc_out == 0) {
             out_buf[count_out] = ch;
             esc_out = 1;
         }
         else if (esc_out == 1) {
             out_buf[count_out] = (char) temp[0];
         }
         else {
             memcpy(&out_buf[count_out], temp, esc_out);
         }
         count_out += esc_out;
     }
     if (count_in < sz) {
         flb_error("Not at boundary but still NULL terminating : %d - '%s'", sz, in_buf);
     }
     out_buf[count_out] = '\0';
     return count_out;
 }

 int flb_unescape_string(const char *buf, int buf_len, char **unesc_buf)
 {
     int i = 0;
     int j = 0;
     char *p;
     char n;

     p = *unesc_buf;
     while (i < buf_len) {
         if (buf[i] == '\\') {
             if (i + 1 < buf_len) {
                 n = buf[i + 1];
                 if (n == 'n') {
                     p[j++] = '\n';
                     i++;
                 }
                 else if (n == 'a') {
                     p[j++] = '\a';
                     i++;
                 }
                 else if (n == 'b') {
                     p[j++] = '\b';
                     i++;
                 }
                 else if (n == 't') {
                     p[j++] = '\t';
                     i++;
                 }
                 else if (n == 'v') {
                     p[j++] = '\v';
                     i++;
                 }
                 else if (n == 'f') {
                     p[j++] = '\f';
                     i++;
                 }
                 else if (n == 'r') {
                     p[j++] = '\r';
                     i++;
                 }
                 else if (n == '\\') {
                     p[j++] = '\\';
                     i++;
                 }
                 i++;
                 continue;
             }
             else {
                 i++;
             }
         }
         p[j++] = buf[i++];
