    29  int flb_parser_json_do(struct flb_parser *parser,
    30                         const char *in_buf, size_t in_size,
    31                         void **out_buf, size_t *out_size,
    32                         struct flb_time *out_time)
    33  {
    34      int i;
    35      int skip;
    36      int ret;
    37      int slen;
    38      int root_type;
    39      double tmfrac = 0;
    40      char *mp_buf = NULL;
    41      char *time_key;
    42      char *tmp_out_buf = NULL;
    43      char tmp[255];
    44      size_t tmp_out_size = 0;
    45      size_t off = 0;
    46      size_t map_size;
    47      size_t mp_size;
    48      size_t len;
    49      msgpack_sbuffer mp_sbuf;
    50      msgpack_packer  mp_pck;
    51      msgpack_unpacked result;
    52      msgpack_object map;
    53      msgpack_object *k = NULL;
    54      msgpack_object *v = NULL;
    55      time_t time_lookup;
    56      struct tm tm = {0};
    57      struct flb_time *t;
    58
    59      /* Convert incoming in_buf JSON message to message pack format */
    60      ret = flb_pack_json(in_buf, in_size, &mp_buf, &mp_size, &root_type);
    61      if (ret != 0) {
    62          return -1;
    63      }
    64
    65      /* Make sure object is a map */
    66      msgpack_unpacked_init(&result);
    67      if (msgpack_unpack_next(&result, mp_buf, mp_size, &off) == MSGPACK_UNPACK_SUCCESS) {
    68          map = result.data;
    69          if (map.type != MSGPACK_OBJECT_MAP) {
    70              flb_free(mp_buf);
    71              msgpack_unpacked_destroy(&result);
    72              return -1;
    73          }
    74      }
    75      else {
    76          if (mp_size > 0) {
    77              flb_free(mp_buf);
    78          }
    79          msgpack_unpacked_destroy(&result);
    80          return -1;
    81      }
    82
    83      /* Export results (might change later) */
    84      tmp_out_buf = mp_buf;
    85      tmp_out_size = mp_size;
    86
    87      /* Do we have some decoders set ? */
    88      if (parser->decoders) {
    89          ret = flb_parser_decoder_do(parser->decoders,
    90                                      mp_buf, mp_size,
    91                                      &tmp_out_buf, &tmp_out_size);
    92          if (ret == 0) {
    93              /* re-process the unpack context */
    94              off = 0;
    95              msgpack_unpacked_destroy(&result);
    96              msgpack_unpacked_init(&result);
    97              msgpack_unpack_next(&result, tmp_out_buf, tmp_out_size, &off);
    98              map = result.data;
    99          }
   100      }
   101
   102      /* Set the possible outgoing buffer */
   103      *out_buf = tmp_out_buf;
   104      *out_size = tmp_out_size;
   105      if (mp_buf != tmp_out_buf) {
   106          flb_free(mp_buf);
   107      }
   108
   109      /* Do time resolution ? */
   110      if (!parser->time_fmt) {
   111          msgpack_unpacked_destroy(&result);
   112          return *out_size;
   113      }
   114
   115      if (parser->time_key) {
   116          time_key = parser->time_key;
   117      }
   118      else {
   119          time_key = "time";
   120      }
   121      slen = strlen(time_key);
   122
   123      /* Lookup time field */
   124      map_size = map.via.map.size;
   125      skip = map_size;
   126      for (i = 0; i < map_size; i++) {
   127          k = &map.via.map.ptr[i].key;
   128          v = &map.via.map.ptr[i].val;
   129
   130          if (k->via.str.size != slen) {
   131              continue;
   132          }
   133
   134          if (strncmp(k->via.str.ptr, time_key, k->via.str.size) == 0) {
   135              /* We found the key, break the loop and keep the index */
   136              if (parser->time_keep == FLB_FALSE) {
   137                  skip = i;
   138                  break;
   139              }
   140              else {
   141                  skip = -1;
   142              }
   143              break;
   144          }
   145
   146          k = NULL;
   147          v = NULL;
   148      }
   149
   150      /* No time_key field found */
   151      if (i >= map_size || !k || !v) {
   152          msgpack_unpacked_destroy(&result);
   153          return *out_size;
   154      }
   155
   156      /* Lookup time */
   157      ret = flb_parser_time_lookup(v->via.str.ptr, v->via.str.size,
   158                                   0, parser, &tm, &tmfrac);
   159      if (ret == -1) {
   160          len = v->via.str.size;
   161          if (len > sizeof(tmp) - 1) {
   162              len = sizeof(tmp) - 1;
   163          }
   164          memcpy(tmp, v->via.str.ptr, len);
   165          tmp[len] = '\0';
   166          flb_warn("[parser:%s] invalid time format %s for '%s'",
   167                   parser->name, parser->time_fmt_full, tmp);
   168          time_lookup = 0;
   169      }
   170      else {
   171          time_lookup = flb_parser_tm2time(&tm);
   172      }
   173
   174      /* Compose a new map without the time_key field */
   175      msgpack_sbuffer_init(&mp_sbuf);
   176      msgpack_packer_init(&mp_pck, &mp_sbuf, msgpack_sbuffer_write);
   177
   178      if (parser->time_keep == FLB_FALSE) {
   179          msgpack_pack_map(&mp_pck, map_size - 1);
   180      }
   181      else {
   182          msgpack_pack_map(&mp_pck, map_size);
   183      }
   184
   185      for (i = 0; i < map_size; i++) {
   186          if (i == skip) {
   187              continue;
   188          }
   189          msgpack_pack_object(&mp_pck, map.via.map.ptr[i].key);
   190          msgpack_pack_object(&mp_pck, map.via.map.ptr[i].val);
   191      }
   192
   193      /* Export the proper buffer */
   194      flb_free(tmp_out_buf);
   195      *out_buf = mp_sbuf.data;
   196      *out_size = mp_sbuf.size;
   197
   198      t = out_time;
   199      t->tm.tv_sec  = time_lookup;
   200      t->tm.tv_nsec = (tmfrac * 1000000000);
   201
   202      msgpack_unpacked_destroy(&result);
   203      return *out_size;
   204  }
