   287  static int ltsv_parser(struct flb_parser *parser,
   288                         const char *in_buf, size_t in_size,
   289                         msgpack_packer *tmp_pck,
   290                         char *time_key, size_t time_key_len,
   291                         time_t *time_lookup, double *tmfrac,
   292                         size_t *map_size)
   293  {
   294      int ret;
   295      struct tm tm = {0};
   296      const unsigned char *label = NULL;
   297      size_t label_len = 0;
   298      const unsigned char *field = NULL;
   299      size_t field_len = 0;
   300      const unsigned char *c = (const unsigned char *)in_buf;
   301      const unsigned char *end = c + in_size;
   302      int last_byte;
   303      int do_pack = FLB_TRUE;
   304
   305      /* if map_size is 0 only count the number of k:v */
   306      if (*map_size == 0) {
   307          do_pack = FLB_FALSE;
   308      }
   309
   310      while (c < end) {
   311          label = c;
   312          while ((c < end) && ltvs_label[*c]) {
   313              c++;
   314          }
   315          label_len = c - label;
   316          if (c == end) {
   317              break;
   318          }
   319
   320          if (*c != ':') {
   321              break;
   322          }
   323          c++;
   324
   325          field = c;
   326          if (c != end) {
   327              while ((c < end) && ltvs_field[*c]) {
   328                  c++;
   329              }
   330          }
   331          field_len = c - field;
   332
   333          if (label_len > 0) {
   334              int time_found = FLB_FALSE;
   335
   336              if (parser->time_fmt && label_len == time_key_len &&
   337                  field_len > 0 &&
   338                  !strncmp((const char *)label, time_key, label_len)) {
   339                  if (do_pack) {
   340                      ret = flb_parser_time_lookup((const char *) field, field_len,
   341                                                    0, parser, &tm, tmfrac);
   342                      if (ret == -1) {
   343                         flb_error("[parser:%s] Invalid time format %s",
   344                                   parser->name, parser->time_fmt_full);
   345                         return -1;
   346                      }
   347                      *time_lookup = flb_parser_tm2time(&tm);
   348                  }
   349                  time_found = FLB_TRUE;
   350              }
   351
   352              if (time_found == FLB_FALSE || parser->time_keep == FLB_TRUE) {
   353                  if (do_pack) {
   354                      if (parser->types_len != 0) {
   355                          flb_parser_typecast((const char*) label, label_len,
   356                                              (const char*) field, field_len,
   357                                              tmp_pck,
   358                                              parser->types,
   359                                              parser->types_len);
   360                      }

80      int do_pack = FLB_TRUE;
    81      int value_str = FLB_FALSE;
    82      int value_escape = FLB_FALSE;
    83
    84      /* if map_size is 0 only count the number of k:v */
    85      if (*map_size == 0) {
    86          do_pack = FLB_FALSE;
    87      }
    88
    89      while (c < end) {
    90          /* garbage */
    91          while ((c < end) && !ident_byte[*c]) {
    92              c++;
    93          }
    94          if (c == end) {
    95              break;
    96          }
    97          /* key */
    98          key = c;
    99          while ((c < end) && ident_byte[*c]) {
   100              c++;
   101          }
   102          if (c == end) {
   103              break;
   104          }
   105
   106          key_len = c - key;
   107          /* value */
   108          value_len = 0;
   109          value_str = FLB_FALSE;
   110          value_escape =  FLB_FALSE;
   111
   112          if (*c == '=') {
   113              c++;
   114              if (c < end) {
   115                  if (*c == '"') {
   116                      c++;
   117                      value = c;
   118                      value_str = FLB_TRUE;
   119                      while (c < end) {
   120                          if (*c != '\\' && *c!= '"') {
   121                              c++;
   122                          }
   123                          else if (*c == '\\') {
   124                              value_escape =  FLB_TRUE;
   125                              c++;
   126                              if (c == end) {
   127                                  break;
   128                              }
   129                              c++;
   130                          }
   131                          else {
   132                              break;
   133                          }
   134                      }
   135                      value_len = c - value;
   136                      if (c < end && *c == '\"') {
   137                          c++;
   138                      }
   139                  }
   140                  else {
   141                     value = c;
   142                     while ((c < end) && ident_byte[*c]) {
   143                        c++;
   144                     }
   145                     value_len = c - value;
   146                  }
   147              }
   148          }
   149
   150          if (key_len > 0) {
   151              int time_found = FLB_FALSE;
   152
   153              if (parser->time_fmt && key_len == time_key_len &&
   154                  value_len > 0 &&
   155                  !strncmp((const char *)key, time_key, key_len)) {
   156                  if (do_pack) {
   157                      ret = flb_parser_time_lookup((const char *) value, value_len,
   158                                                    0, parser, &tm, tmfrac);
   159                      if (ret == -1) {
   160                          flb_error("[parser:%s] Invalid time format %s",
   161                                    parser->name, parser->time_fmt_full);
   162                          return -1;
   163                      }
   164                      *time_lookup = flb_parser_tm2time(&tm);
   165                  }
   166                  time_found = FLB_TRUE;
   167              }
   168
   169              if (time_found == FLB_FALSE || parser->time_keep == FLB_TRUE) {
   170                  if (do_pack) {
   171                      if (parser->types_len != 0) {
   172                          flb_parser_typecast((const char*) key, key_len,
   173                                              (const char*) value, value_len,
   174                                              tmp_pck,
   175                                              parser->types,
   176                                              parser->types_len);
   177                      }
   178                      else {
   179                          msgpack_pack_str(tmp_pck, key_len);
   180                          msgpack_pack_str_body(tmp_pck, (const char *)key, key_len);
   181                          if (value_len == 0) {
   182                              if (value_str == FLB_TRUE) {
   183                                  msgpack_pack_str(tmp_pck, 0);
   184                              }
   185                              else {
   186                                  msgpack_pack_nil(tmp_pck);
   187                              }
   188                          }
   189                          else {
   190                              if (value_escape == FLB_TRUE) {
   191                                  int out_len;
   192                                  char *out_str;
   193
   194                                  out_str = flb_malloc(value_len + 1);
   195                                  if (out_str == NULL) {
   196                                      flb_errno();
   197                                      return -1;
   198                                  }
   199                                  out_str[0] = 0;
   200                                  flb_unescape_string_utf8((const char *)value,
   201                                                            value_len,
   202                                                            out_str);
   203                                  out_len = strlen(out_str);
   204
   205                                  msgpack_pack_str(tmp_pck, out_len);
   206                                  msgpack_pack_str_body(tmp_pck,
   207                                                        out_str,
   208                                                        out_len);
   209
   210                                  flb_free(out_str);
   211                              }
   212                              else {
   213                                  msgpack_pack_str(tmp_pck, value_len);
   214                                  msgpack_pack_str_body(tmp_pck,
   215                                                        (const char *)value,
   216                                                        value_len);
   217                              }
   218                          }
   219                      }
   220                  }
   221                  else {
   222                      (*map_size)++;
   223                  }
   224              }
   225          }
   226
   227          if (c == end) {
   228              break;
   229          }
