    34  /* Decode a stringified JSON message */
    35  static int decode_json(struct flb_parser_dec *dec,
    36                         const char *in_buf, size_t in_size,
    37                         char **out_buf, size_t *out_size, int *out_type)
    38  {
    39      int ret;
    40      int root_type;
    41      char *buf;
    42      const char *p;
    43      size_t size;
    44      size_t len;
    45
    46      p = in_buf;
    47      while (*p == ' ') p++;
    48
    49      len = in_size - (p - in_buf);
    50
    51      /* It must be a map or array */
    52      if (p[0] != '{' && p[0] != '[') {
    53          return -1;
    54      }
    55
    56      ret = flb_pack_json(p, len, &buf, &size, &root_type);
    57      if (ret != 0) {
    58          return -1;
    59      }
    60
    61      /* Only process a packed JSON object */
    62      if (root_type != FLB_PACK_JSON_OBJECT) {
    63          flb_free(buf);
    64          return -1;
    65      }
    66
    67      *out_buf = buf;
    68      *out_size = size;
    69      *out_type = TYPE_OUT_OBJECT;
    70
    71      return 0;
    72  }
