   140                                         char **out_buf, size_t *out_size)
   141  {
   142      int i;
   143      int ret;
   144      int map_size = 0;
   145      size_t in_off = 0;
   146      size_t extra_off = 0;
   147      msgpack_sbuffer mp_sbuf;
   148      msgpack_packer  mp_pck;
   149      msgpack_unpacked in_result;
   150      msgpack_unpacked extra_result;
   151      msgpack_object k;
   152      msgpack_object v;
   153      msgpack_object map;
   154
   155      msgpack_unpacked_init(&in_result);
   156      msgpack_unpacked_init(&extra_result);
   157
   158      /* Check if the extra buffer have some serialized data */
   159      ret = msgpack_unpack_next(&extra_result, extra_buf, extra_size, &extra_off);
   160      if (ret != MSGPACK_UNPACK_SUCCESS) {
   161          msgpack_unpacked_destroy(&in_result);
   162          msgpack_unpacked_destroy(&extra_result);
   163          return -1;
   164      }
   165      msgpack_unpack_next(&in_result, in_buf, in_size, &in_off);
   166
   167
   168      msgpack_sbuffer_init(&mp_sbuf);
   169      msgpack_packer_init(&mp_pck, &mp_sbuf, msgpack_sbuffer_write);
   170
   171      map_size = in_result.data.via.map.size;
   172      map_size += extra_result.data.via.map.size;
   173
   174      msgpack_pack_map(&mp_pck, map_size);
   175      map = in_result.data;
   176      for (i = 0; i < map.via.map.size; i++) {
   177          k = map.via.map.ptr[i].key;
   178          v = map.via.map.ptr[i].val;
   179          msgpack_pack_object(&mp_pck, k);
   180          msgpack_pack_object(&mp_pck, v);
   181      }
   182
   183      map = extra_result.data;
   184      for (i = 0; i < map.via.map.size; i++) {
   185          k = map.via.map.ptr[i].key;
   186          v = map.via.map.ptr[i].val;
   187          msgpack_pack_object(&mp_pck, k);
   188          msgpack_pack_object(&mp_pck, v);
   189      }
   190
   191      msgpack_unpacked_destroy(&in_result);
   192      msgpack_unpacked_destroy(&extra_result);
   193
   194      *out_buf = mp_sbuf.data;
   195      *out_size = mp_sbuf.size;
   196
   197      return 0;
   198  }
